"""Four original surviving finite panel front domains only, no geometry edits."""
from pathlib import Path
import numpy as np,trimesh,json,hashlib
R=Path(__file__).resolve().parent;H=lambda p:hashlib.sha256(p.read_bytes()).hexdigest();expected='511db129ca786dcaedee1d1c5a4bf777945b454b0b53f166eff1e7f8d67f0e28';assert H(R/'model.stl')==expected
m=trimesh.load(R/'model.stl',force='mesh',process=True);assert len(m.faces)==1752
t=m.triangles;n=m.face_normals;e=.0001;a=np.full(len(t),3,np.int32);D={}
for name,x0,x1,z0,z1,mat,count in [('top_left',-38,-32,94,111,0,6),('top_right',20,26,94,111,0,6),('middle_left',-13,-7,59,94,1,10),('lower_left',-38,-32,41,57,2,6)]:
 hit=(abs(t[:,:,1]+19.9).max(1)<e)&(t[:,:,0].min(1)>=x0-e)&(t[:,:,0].max(1)<=x1+e)&(t[:,:,2].min(1)>=z0-e)&(t[:,:,2].max(1)<=z1+e);ids=np.flatnonzero(hit);assert len(ids)==count,(name,len(ids));D[name]=ids.tolist();a[ids]=mat
ad=m.face_adjacency;cop=(n[ad[:,0]]*n[ad[:,1]]).sum(1)>.999999;cs=trimesh.graph.connected_components(ad[cop],nodes=np.arange(len(t)),min_len=1);assert all(len(set(a[c]))==1 for c in cs);assert np.bincount(a).tolist()==[12,10,6,1724]
pal=[('Observed top panel fronts muted yellow','#C7BA63'),('Observed middle-left panel front pale ochre','#D0BC87'),('Observed lower-left panel front terracotta','#B77858'),('UNVERIFIED treehidden panel walls glass roof neutral','#B8BAB5')]
np.savez_compressed(R/'color-mesh.npz',vertices=m.vertices,faces=m.faces,materials=a);(R/'palette.json').write_text(json.dumps(pal,indent=2)+'\n');q={'palette':[{'id':i,'name':name,'hex':col,'faces':int((a==i).sum())}for i,(name,col)in enumerate(pal)],'domain_face_indices':D,'coplanar_components':len(cs),'partial_color_incomplete':True,'fully_colored_exterior':False,'geometry_policy':'1752 original triangles unchanged','limits':['Four whole original notched front panel domains y-19.9, allvertices finitebounds, no centroid splitting.','Top yellow6+6/middleleft paleochre10/lowerleft terracotta6.','Whole treeshaded middle-right panel neutral, not partially colored above trees.','Gray walls white bands returns windowbacks tanks fullcircumferences roof rear base neutral.','Unknown photo date, webpage year not capture or currentcondition; new building only, no adjacent old buildings.']};(R/'appearance-materials.json').write_text(json.dumps(q,indent=2)+'\n');(R/'COLOR-ASSIGNMENT-QA.json').write_text(json.dumps({'status':'PASS','original_STL_sha256':expected,'triangles':1752,'color_mesh_sha256':H(R/'color-mesh.npz')},indent=2));print(q['palette'],'components',len(cs))
